contract InvMutTest {
    C c;

    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0, "balance always nonnegative");
        require(recipient != address(0), "recipient nonzero");

        uint256 contractBalBefore = address(c).balance;
        uint256 recipientBalBefore = recipient.balance;

        // Ensure c has some balance to withdraw so the rule is meaningful.
        require(contractBalBefore > 0, "c must hold ether");

        // The checker deploys c with this contract as owner, so msg.sender == owner here.
        c.withdrawAll(recipient); if (__ESBMC_reverted()) return;

        uint256 contractBalAfter = address(c).balance;
        uint256 recipientBalAfter = recipient.balance;

        assert(contractBalAfter == 0 && recipientBalAfter == recipientBalBefore + contractBalBefore);
    }

    receive() external payable {}
}

